CREATE POLICY "Users upload proofs in own folder" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'proofs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Signed-in users can view proofs" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'proofs');
CREATE POLICY "Users delete proofs in own folder" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'proofs' AND (storage.foldername(name))[1] = auth.uid()::text);